def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Calculate XOR sum of Grundy numbers for all piles
    nim_sum = 0

    for x in a:
        nim_sum ^= grundy(x, k)

    if nim_sum > 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

def grundy(x, k):
    """Calculate Grundy number for a pile of size x with parameter k"""
    if x == 0:
        return 0

    memo = {}

    def helper(val):
        if val in memo:
            return memo[val]

        # Option 1: Remove 1 cow -> get G(val-1)
        reachable = {helper(val - 1)}

        # Option 2: If val is even, replace with k piles of val/2
        if val % 2 == 0:
            if k % 2 == 0:
                reachable.add(0)  # Even number of same Grundy values XOR to 0
            else:
                gx = helper(val // 2)
                reachable.add(gx)  # Odd number of same Grundy values XOR to gx

        result = 0
        while result in reachable:
            result += 1
        memo[val] = result
        return result

    return helper(x)

# Test with provided examples
# Test 1: 1 2, pile 3 -> Nicky should win
# Test 2: 2 1, piles 3 4 -> Kevin should win
# Test 3: 6 1, piles 1 4 4 4 2 2 -> Kevin should win
