from collections import deque

def solution(input_data: str) -> str:
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        x, y, w = map(int, lines[2 + i].split())
        edges.append({'x':x, 'y':y, 'w':w, 'id':i+1})
        adj[x].append((y, i+1))
        adj[y].append((x, i+1))

    def check(s, t, removed_ids):
        visited = {s}
        queue = deque([s])
        while queue:
            u = queue.popleft()
            for v, e_id in adj[u]:
                if e_id not in removed_ids and v not in visited:
                    visited.add(v)
                    queue.append(v)
                    if v == t:
                        return True
        return False

    # If already disconnected
    if not check(s, t, set()):
        return "0\n0\n"

    # Try removing 1 edge
    best_single = float('inf')
    single_edges = []

    for edge in edges:
        if not check(s, t, {edge['id']}):
            if edge['w'] < best_single:
                best_single = edge['w']
                single_edges = [edge['id']]

    # Try removing 2 edges
    best_pair = (float('inf'), [])

    # Simple brute force with pruning
    for i in range(len(edges)):
        if best_single == float('inf') and edges[i]['w'] >= best_single:
            break

        for j in range(i, len(edges)):
            removed = {edges[i]['id'], edges[j]['id']}
            if i == j:
                removed = {edges[i]['id']}

            if not check(s, t, removed):
                total = edges[i]['w'] + (edges[j]['w'] if i != j else 0)
                if i == j:
                    total = edges[i]['w']
                if (total, (i == j)) < best_pair[0]:
                    best_pair = (total, [edges[i]['id'], edges[j]['id']])

    # Choose best solution
    if best_single == float('inf') and best_pair[0] == float('inf'):
        return "-1"

    if best_single < best_pair[0]:
        ans = (best_single, 1, [single_edges[0]])
    else:
        ans = (best_pair[0], 2, best_pair[1])

    return f"{ans[0]}\n{ans[1]}\n{' '.join(map(str, sorted(ans[2])))}"
