    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total = 0

        for l, r in offers:
            length = r - l + 1
            if length >= x:
                conflict = False
                for day in range(l, r + 1):
                    if occupied[day]:
                        conflict = True
                        break
                if not conflict:
                    for day in range(l, r + 1):
                        occupied[day] = True
                    total += length

        result.append(str(total))

