2. Find the maximum possible score for that first-place score

Key insights:
- Students at ranks 1 to k tied at score S means students 1..k all get score S
- The last query (p_q, s_q) constrains: student p_q must get exactly s_q
- For k students to tie at rank 1 with score S: S >= s_i for all i where p_i <= k
- Total score t must be achievable with k students at S and the remaining (m-k) students distributed appropriately

```python
import sys

def solution(input_data):
    lines = input_data.strip().split('\n')
    line_idx = 0

    n, m = map(int, lines[line_idx].split())
    line_idx += 1

    l = []
    r = []
    for _ in range(n):
        l.append(int(lines[line_idx]))
        r.append(int(lines[line_idx + 1]))
        line_idx += 2

    q = int(lines[line_idx])
    line_idx += 1

    queries = []
    for _ in range(q):
        queries.append((int(lines[line_idx]), int(lines[line_idx + 1])))
        line_idx += 2

    t = int(lines[line_idx])

    if q > 0:
        queries.sort(key=lambda x: x[0])

    for i in range(1, q):
        if queries[i][1] > queries[i-1][1]:
            return "-1 -1\n"

    if q > 0:
        last_rank, last_score = queries[-1]
        min_sum = last_score * last_rank
        if min_sum > t:
            return "-1 -1\n"

    remaining_sum = t - (last_score * last_rank) if q > 0 else t
    remaining_students = m - last_rank if q > 0 else m

    min_possible = 0
    for i in range(n):
        min_possible += l[i]

    if min_possible > t:
        return "-1 -1\n"

    max_possible = 0
    for i in range(n):
        max_possible += r[i]

    if max_possible < t:
        return "-1 -1\n"

    valid_scores = []

    for i in range(q):
        rank, score = queries[i]
        if score > n or score < 0:
            return "-1 -1\n"

        for k in range(1, rank + 1):
            if k > m:
                continue
            max_remaining = (m - k) * n
            if k * score <= t <= k * n + max_remaining:
                if 0 <= remaining_sum <= remaining_students * n:
                    valid_scores.append((score, k))

    if valid_scores:
        valid_scores.sort(key=lambda x: -x[1])
        max_k = valid_scores[0][1]

        all_scores = sorted(set(s for s, k in valid_scores if k >= max_k), reverse=True)

        if all_scores:
            return f"{max_k} {all_scores[0]}\n"

    return "-1 -1\n"

