        if len(visited_tuple) == k:
            return 1

        total = 0

        # Try all possible next planets from 1 to current + m
        for next_planet in range(1, min(n, current + m) + 1):
            if next_planet not in visited_tuple:
                new_visited = visited_tuple + (next_planet,)
                total = (total + count_ways(next_planet, new_visited)) % MOD

        return total

    # Sum over all possible starting planets
    result = 0
    for start in range(1, n + 1):
        result = (result + count_ways(start, (start,))) % MOD

    return str(result)
