    n1, n2, m = map(int, lines[0].split())
    edges = []
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        edges.append((u - 1, v - 1, i))

    # Compute original degrees
    deg_left = [0] * n1
    deg_right = [0] * n2
    for u, v, idx in edges:
        deg_left[u] += 1
        deg_right[v] += 1

    min_deg = min(min(deg_left), min(deg_right)) if (deg_left and deg_right) else 1

    output_lines = []

    for k in range(1, min_deg + 1):
        selected = set()
        curr_left = [0] * n1
        curr_right = [0] * n2

        while True:
            still_needed = False

            for u in range(n1):
                if curr_left[u] < k:
                    still_needed = True
                    break
            if not still_needed:
                for v in range(n2):
                    if curr_right[v] < k and not still_needed:
                        still_needed = True

            if not still_needed:
                break

            # Find an edge that connects two unsatisfied vertices
            found = False
            for u in range(n1):
                if curr_left[u] >= k:
                    continue
                for (u0, v0, idx) in edges:
                    if u0 == u and idx not in selected:
                        if curr_right[v0] < k:
                            selected.add(idx)
                            curr_left[u0] += 1
                            curr_right[v0] += 1
                            found = True
                            break
                if found:
                    break

            # If no such edge, just find any edge incident to unsatisfied vertex
