def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    t = lines[1]

    # For each character A, B, C, D, find the longest consecutive run in t
    # Toastman will choose to build s using the character with smallest max run
    # Appleman can use at most one such run per step, so if we pick character c
    # with max_run = k, to build (n) occurrences we need ceil(n/k) steps

    max_runs = {}
    for c in 'ABCD':
        current_run = 0
        max_run = 0
        for ch in t:
            if ch == c:
                current_run += 1
                max_run = max(max_run, current_run)
            else:
                current_run = 0
        max_runs[c] = max_run

    # The minimum max run across all four characters
    min_max_run = min(max_runs[c] for c in 'ABCD')

    # Answer is ceil(n / min_max_run)
    if min_max_run == 0:
        return str(n)

    ans = (n + min_max_run - 1) // min_max_run
    return str(ans)
