def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n = int(lines[0])

    adj = [[] for _ in range(n + 1)]
    for i in range(1, n):
        parts = lines[i].split()
        if parts:
            a, b = int(parts[0]), int(parts[1])
            adj[a].append(b)
            adj[b].append(a)

    # Precompute subtree sizes for optimization
    subtree_size = [0] * (n + 1)

    def dfs(u, p):
        dp = [0] * (n + 1)
        dp[1] = 1  # Component of size 1 (just u), no completed subcomponents

        for v in adj[u]:
            if v == p:
                continue

            child_dp = dfs(v, u)

            # Get actual subtree size of child
            v_max_size = 0
            for size in range(1, len(child_dp)):
                if child_dp[size] > 0:
                    v_max_size = max(v_max_size, size)

            new_dp = [0] * (n + 1)

            # Try all combinations of current size and child size
            for current_s in range(1, n + 1):
                if dp[current_s] == 0:
                    continue

                for child_s in range(1, v_max_size + 1):
                    if child_dp[child_s] == 0:
                        continue

                    # Option 1: Keep edge - merge components
                    if current_s + child_s <= n:
                        new_dp[current_s + child_s] = max(
                            new_dp[current_s + child_s],
                            dp[current_s]
                        )

                    # Option 2: Cut edge - child component becomes complete
                    new_dp[current_s] = max(
                        new_dp[current_s],
                        dp[current_s] * child_s
                    )

            dp = new_dp

        return dp

    root_dp = dfs(1, 0)

    # Answer is max(dp[s] * s) for all possible sizes s
    # because the root's component can also be completed
    ans = 0
    for s in range(1, n + 1):
        if root_dp[s] > 0:
            ans = max(ans, root_dp[s] * s)

    return str(ans)
