def solution(input_str):
    """
    Solution for Hiasat's Handle problem.

    Key insight: Two friends cannot both be happy if they visit the same segment
    (between two '1' events). This forms a conflict graph where we need to find
    the Maximum Independent Set.

    With m <= 40 friends, we use recursive backtracking with pruning.
    """
    lines = input_str.strip().split('\n')

    if not lines or not lines[0]:
        return '0'

    # Parse n and m (though m isn't directly used beyond understanding constraints)
    first_line = lines[0].split()
    n, m = int(first_line[0]), int(first_line[1])

    # Find all type 1 event line numbers
    type1_indices = []
    for i in range(1, len(lines)):
        if lines[i].startswith('1'):
            type1_indices.append(i)

    # If no type 1 events, no segments possible
    if not type1_indices:
        return '0'

    # Build mapping: friend -> set of segment indices they visit
    friend_segments = {}

    # Helper: determine which segment a line belongs to
    def get_segment(line_idx):
        for seg in range(len(type1_indices) - 1):
            if type1_indices[seg] < line_idx <= type1_indices[seg + 1]:
                return seg
        # After the last type 1 event
        if line_idx > type1_indices[-1]:
            return len(type1_indices) - 1
        return -1

    # Process all type 2 events
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2 and parts[0] == '2':
            friend = parts[1]
            seg = get_segment(i)
            if seg >= 0:
                if friend not in friend_segments:
                    friend_segments[friend] = set()
                friend_segments[friend].add(seg)

    # If no friends visited
    friends_list = list(friend_segments.keys())
    num_friends = len(friends_list)

    if num_friends == 0:
        return '0'

    # Build conflict graph: edge between i and j if they share a segment
    adj = [[] for _ in range(num_friends)]
    for i in range(num_friends):
        for j in range(i + 1, num_friends):
            if friend_segments[friends_list[i]] & friend_segments[friends_list[j]]:
                adj[i].append(j)
                adj[j].append(i)

    # Find Maximum Independent Set using backtracking with pruning
    # Sort by degree descending for better pruning
    order = sorted(range(num_friends), key=lambda x: len(adj[x]), reverse=True)

    max_result = [0]
    visited = [False] * num_friends

    def dfs(idx):
        nonlocal max_result

        # If all nodes processed, update max
        if idx == num_friends:
            current = sum(visited)
            max_result[0] = max(max_result[0], current)
            return

        # Pruning: if remaining nodes can't improve max_result
        remaining = num_friends - idx
        if max_result[0] + remaining <= max_result[0]:
            return

        node = order[idx]

        # Calculate degree (number of neighbors that are in set)
        conflict_count = sum(1 for neighbor in adj[node] if visited[neighbor])

        # Option 1: Try including this node (only if no neighbor is in set)
        if conflict_count == 0:
            visited[node] = True
            dfs(idx + 1)
            visited[node] = False

        # Option 2: Always try excluding this node
        dfs(idx + 1)

    dfs(0)

    return str(max_result[0])


