def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    idx = 1
    for _ in range(n - 1):
        u, v = map(int, lines[idx].split())
        adj[u].append(v)
        adj[v].append(u)
        idx += 1

    ans = []

    for k in range(1, n + 1):
        if k == 1:
            ans.append(n)
            continue

        # Post-order traversal (bottom-up)
        order = []
        stack = [1]
        parent = [0] * (n + 1)
        visited = [False] * (n + 1)

        while stack:
            u = stack.pop()
            visited[u] = True
            order.append(u)
            for v in adj[u]:
                if not visited[v]:
                    parent[v] = u
                    stack.append(v)

        dp = [0] * (n + 1)  # Length of the path extending from this node

        for u in reversed(order):
            pending = []
            for v in adj[u]:
                if v != parent[u]:
                    pending.append(dp[v])

            pending.sort(reverse=True)

            formed = 0
            i = 0
            while i + 1 < len(pending):
                if pending[i] + pending[i+1] + 1 == k:
                    formed += 1
                    i += 2
                else:
                    i += 1

            if pending and pending[0] >= k - 1:
                dp[u] = k - 1
            else:
                dp[u] = pending[0] + 1 if pending else 0

        if dp[1] >= k:
            ans.append(formed + dp[1] - k + 1)
        else:
            ans.append(formed)

    return '\n'.join(map(str, ans))
