            self.current_root = self._copy_root(self.current_root)
        return self._query_max(self.current_root, q, self.min_q, self.max_q)

    def _copy_root(self, node):
        """Deep copy root node for persistence"""
        if node is None:
            return None
        new_node = LiChaoNode(node.l, node.r)
        new_node.left = node.left
        new_node.right = node.right
        new_node.line = node.line
        return new_node

    def _add_line(self, node, m, c, l, r):
        """Recursively add line to LiChao Tree"""
        if node is None:
            node = LiChaoNode(l, r)

        mid = (l + r) // 2
        f_mid = node.line[0] * mid + node.line[1] if node.line is not None else float('-inf')
        g_mid = m * mid + c

        if g_mid > f_mid:
            # Switch line at this node
            temp = node.line
            node.line = (m, c)
            node.line = temp

        if l == r:
            return node

        # Decide which child to recurse into
        if node.line[0] * l + node.line[1] > float('-inf'):
            if node.left is None:
                node.left = LiChaoNode(l, mid)
            self._add_line(node.left, m, c, l, mid)
        elif node.line[0] * r + node.line[1] > float('-inf'):
            if node.right is None:
                node.right = LiChaoNode(mid + 1, r)
            self._add_line(node.right, m, c, mid + 1, r)

        return node

    def _query_max(self, node, q, l, r):
        """Query maximum value at point q"""
        result = float('-inf')
        if node is not None:
            result = node.line[0] * q + node.line[1]

