                    delta -= 1
            else:
                # Was not inversion, will not be: no delta
                pass

        # For k > ri:
        # (ri, k) is inversion before if B > P[k]
        # After: A > P[k]
        for k in range(ri + 1, n):
            if B > P[k]:
                if A > P[k]:
                    # Was inversion, will be: no change
                    pass
                else:
                    # Was inversion, will not be: -1
                    delta -= 1
            else:
                # Was not inversion, will not be: no change
                pass

