def calculate_delta(P, li, ri):
    """Calculate inversion count change when swapping P[li] and P[ri] (assume li < ri)"""
    A = P[li]
    B = P[ri]
    delta = 0

    if A == B:
        return 0

    # Pair (li, ri) itself
    if A > B:
        # Was inversion, after swap it won't be (A < B after)
        delta -= 1
    else:
        # Was not inversion, after it will be
        delta += 1

    # For positions between li and ri
    for k in range(li + 1, ri):
        if A > P[k]:
            # Was inversion: A > P[k], after: B > P[k]
            if B > P[k]:
                delta += 0
            else:
                delta -= 1
        else:
            # Was not inversion: A < P[k], after: B < P[k]
            if B < P[k]:
                delta += 0
            else:
                delta += 1

    # For positions before li
    for k in range(0, li):
        if P[k] > A:
            # Was inversion: P[k] > A, after: P[k] > B
            if P[k] > B:
                delta += 0
            else:
                delta -= 1
        else:
            if P[k] > B:
                delta += 1
            else:
                delta += 0

    # For positions after ri  
    for k in range(ri + 1, len(P)):
        if B > P[k]:
            # Was inversion: B > P[k], after: A > P[k]
            if A > P[k]:
                delta += 0
            else:
                delta -= 1
        else:
            if A > P[k]:
                delta += 1
            else:
                delta += 0

    return delta
