# Complete Solution
def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, q = map(int, lines[0].split())

    P = list(range(1, n + 1))

    def calculate_delta(idx_a, idx_b):
        A = P[idx_a]
        B = P[idx_b]
        swap_a = min(idx_a, idx_b)
        swap_b = max(idx_a, idx_b)

        delta = 0

        if A > B:
            delta -= 1
        else:
            delta += 1

        for k in range(n):
            if k == swap_a or k == swap_b:
                continue

            # Determine the pair
            if k < swap_a:
                # Pair (k, swap_a)
                # Before: P[k] > P[swap_a]
                # After: P[k] > P[swap_b] (which is B)
                was_inv = P[k] > A
                now_inv = P[k] > B
                if was_inv and not now_inv:
                    delta -= 1
                elif not was_inv and now_inv:
                    delta += 1

            elif k < n:
                # k > swap_b, so pair (swap_b, k)
                # Before: B > P[k]
                # After: A > P[k]
                was_inv = B > P[k]
                now_inv = A > P[k]
                if was_inv and not now_inv:
                    delta -= 1
                elif not was_inv and now_inv:
                    delta += 1

        for k in range(swap_a + 1, swap_b):
            # Position between: pair (swap_a, k)
            was_inv = A > P[k]
            now_inv = B > P[k]
            if was_inv and not now_inv:
                delta -= 1
            elif not was_inv and now_inv:
                delta += 1

        return delta

    output_lines = []
    current = 0

    for i in range(1, q + 1):
        li, ri = map(int, lines[i].split())
        li -= 1
        ri -= 1

        idx_a, idx_b = sorted((li, ri))

        current += calculate_delta(idx_a, idx_b)
        P[idx_a], P[idx_b] = P[idx_b], P[idx_a]
        output_lines.append(str(current))

    return '\n'.join(output_lines)
