def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    n, q = map(int, lines[0].split())
    P = list(range(1, n + 1))

    def get_delta(i, j):
        """Calculate inversion change when swapping positions i and j"""
        a, b = min(i, j), max(i, j)
        val_a, val_b = P[a], P[b]
        delta = 1 if val_a < val_b else -1  # The swap pair itself

        # For all other positions that form a pair with i or j
        for k in range(n):
            if k == a or k == b:
                continue

            # Position k is before both
            if k < a:
                was_inv = P[k] > val_a
                now_inv = P[k] > val_b
                if was_inv and not now_inv:
                    delta -= 1
                elif not was_inv and now_inv:
                    delta += 1

            # Position k is after both
            elif k > b:
                was_inv = val_b > P[k]
                now_inv = val_a > P[k]
                if was_inv and not now_inv:
                    delta -= 1
                elif not was_inv and now_inv:
                    delta += 1

        # Positions between a and b
        for k in range(a + 1, b):
            was_inv = val_a > P[k]
            now_inv = val_b > P[k]
            if was_inv and not now_inv:
                delta -= 1
            elif not was_inv and now_inv:
                delta += 1

        return delta

    inversion_count = 0
    output = []

    for line in lines[1:]:
        if not line.strip():
            continue
        l, r = map(int, line.split())
        l -= 1
        r -= 1

        if l >= 0 and r < n:
            inv_delta = get_delta(l, r)
            inversion_count += inv_delta
            P[l], P[r] = P[r], P[l]
            output.append(str(inversion_count))

    return '\n'.join(output)
